"use client";

/**
 * Checkbox: a yes/no choice, or a partly selected group (indeterminate).
 * Purpose: wraps Radix Checkbox so keyboard and screen reader behaviour is correct. Generated by
 *   shadcn, then re-themed to Grove. Owner: design system.
 * Props: every Radix Checkbox prop (checked, onCheckedChange, disabled, id, name...).
 * Responsive: a 22 px box; put it in a Label so the whole row is the click target.
 * Accessibility: Space toggles; always has a visible label. Checked is shown by a tick, not by colour alone.
 * States: unchecked, checked, indeterminate, hover, focus, disabled, error (aria-invalid).
 * Dependencies: radix Checkbox, lucide icons, cn. Tests: controls.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .check).
 */
import { Check, Minus } from "lucide-react";
import { Checkbox as CheckboxPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function Checkbox({ className, ...props }: ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer grid size-(--size-check) shrink-0 place-content-center rounded-xs border-[length:var(--bw-field)] border-line-input bg-surface text-on-primary",
        "transition-colors duration-(--dur-fast) hover:border-primary",
        "data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=indeterminate]:border-primary data-[state=indeterminate]:bg-primary",
        "aria-invalid:border-[length:var(--bw-error)] aria-invalid:border-danger",
        "disabled:cursor-not-allowed disabled:border-line-strong disabled:bg-canvas-sunken disabled:text-subtle",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center"
      >
        {props.checked === "indeterminate" ? (
          <Minus aria-hidden="true" className="size-4" strokeWidth={3} />
        ) : (
          <Check aria-hidden="true" className="size-4" strokeWidth={3} />
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox };
